            return '<h2>Reality Encyclopedia</h2><div class="mv-two">' + docs.map(d => '<article class="mv-encyclopedia-card"><small>' + esc(d.kind) + '</small><h3>' + esc(d.title) + '</h3><p>' + esc(d.text) + '</p></article>').join('') + '</div>' + (docs.length ? '' : '<p>Chưa có mục này tại mốc đang xem.</p>');
